'use client';
import { useCallback, useEffect, useId, useRef, useState, type CSSProperties, type FormEvent, type KeyboardEvent, type ReactNode } from 'react';
import { flushSync } from 'react-dom';
import { cssEase, duration as D, flip, useStudioMotion, viewTransition } from '../../../motion';
import {
  EMPTY, GOALS, INTEGRATIONS, ORDER, PREP_LIST, ROLES, STEPS,
  allowed, clear, hashFor, indexOf, load, save, stepFromHash, validateEmail, validateKitchen,
  type Data, type GoalId, type IntegrationId, type RoleId, type StepId,
} from './data';
import { Check, MorphButton, type MorphPhase } from './MorphButton';
import styles from './styles.module.css';

/** Answer elements and their ticket lines share these names so the View Transitions API can fly one into the other. */
const fly = (name: string | false | null | undefined): CSSProperties | undefined =>
  name ? ({ viewTransitionName: `larder-a-${name}`, viewTransitionClass: 'larder-fly' } as CSSProperties) : undefined;

const TRANSITION_CSS = `
::view-transition-group(larder-step) { animation-duration: ${D.moderate}ms; }
::view-transition-old(larder-step) { animation: ${D.base}ms ${cssEase('exit')} both larder-out; }
::view-transition-new(larder-step) { animation: ${D.moderate}ms ${cssEase('emphasized')} 60ms both larder-in; }
:root[data-larder-dir='back']::view-transition-old(larder-step) { animation-name: larder-out-back; }
:root[data-larder-dir='back']::view-transition-new(larder-step) { animation-name: larder-in-back; }
::view-transition-old(larder-progress) { display: none; }
::view-transition-new(larder-progress) { animation: none; }
::view-transition-group(larder-ticket), ::view-transition-group(*.larder-fly) { animation-duration: ${D.slow - 80}ms; animation-timing-function: ${cssEase('emphasized')}; }
:root[data-larder-vt='fade']::view-transition-group(*) { animation: none; }
:root[data-larder-vt='fade']::view-transition-old(*) { animation: 180ms linear both larder-fade-out; }
:root[data-larder-vt='fade']::view-transition-new(*) { animation: 180ms linear both larder-fade-in; }
@keyframes larder-out { to { opacity: 0; transform: translateX(-28px); } }
@keyframes larder-in { from { opacity: 0; transform: translateX(28px); } }
@keyframes larder-out-back { to { opacity: 0; transform: translateX(28px); } }
@keyframes larder-in-back { from { opacity: 0; transform: translateX(-28px); } }
@keyframes larder-fade-out { to { opacity: 0; } }
@keyframes larder-fade-in { from { opacity: 0; } }
`;

function RoleIcon({ id }: { id: RoleId }) {
  const p = { fill: 'none', stroke: 'currentColor', strokeWidth: 1.6, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  return (
    <svg className={styles.roleIcon} viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      {id === 'head-chef' ? <><path {...p} d="M4 20 15.5 8.5l3.5 1-9 9.5Z" /><path {...p} d="m15.5 8.5 3-3.5a1.6 1.6 0 0 1 2.3 2.2L19 9.5" /></> : null}
      {id === 'owner' ? <><circle {...p} cx="8" cy="8" r="4" /><path {...p} d="m11 11 9 9M16.5 16.5l2-2M14 14l2-2" /></> : null}
      {id === 'sous-chef' ? <><path {...p} d="M12 21v-7" /><path {...p} d="M12 14c-3.5 0-5-3.4-5-6.5S9.2 3 12 3s5 1.4 5 4.5-1.5 6.5-5 6.5Z" /><path {...p} d="M12 3c-1.4 1.6-2 3.4-2 5.6S10.6 12.4 12 14c1.4-1.6 2-3.2 2-5.4S13.4 4.6 12 3Z" /></> : null}
      {id === 'manager' ? <><rect {...p} x="5" y="4.5" width="14" height="16.5" rx="2" /><path {...p} d="M9 4.5V3h6v1.5M8.5 10h7M8.5 13.5h7M8.5 17h4" /></> : null}
    </svg>
  );
}

function Bang() {
  return <svg className={styles.errIcon} viewBox="0 0 16 16" aria-hidden="true" focusable="false"><circle cx="8" cy="8" r="7" /><path d="M8 4.5v4.2M8 11.3v.2" /></svg>;
}

/* ── Ticket on the rail: the running summary every answer flies into ──── */
function Ticket({ data, step, flight }: { data: Data; step: StepId; flight: StepId | null }) {
  const role = ROLES.find((r) => r.id === data.role);
  const goals = GOALS.filter((g) => data.goals.includes(g.id));
  const connected = INTEGRATIONS.filter((i) => data.connected.includes(i.id));
  const skipped = (s: StepId) => data.skipped.includes(s);
  type Line = { s: StepId; label: string; value: string | null; items?: { key: string; text: string }[] };
  const lines: Line[] = [
    { s: 'kitchen', label: 'Kitchen', value: data.kitchen.trim() || null },
    { s: 'role', label: 'Role', value: role?.name ?? (skipped('role') ? 'Skipped' : null) },
    { s: 'goals', label: 'First lists', value: goals.length ? '' : skipped('goals') ? 'Prep lists (default)' : null, items: goals.map((g) => ({ key: `goal-${g.id}`, text: g.name })) },
    { s: 'connect', label: 'Connected', value: connected.length ? '' : indexOf(step) > indexOf('connect') ? 'Sample data' : null, items: connected.map((i) => ({ key: `int-${i.id}`, text: i.name })) },
    { s: 'brigade', label: 'Brigade', value: data.invited.length ? `${data.invited.length} invited` : skipped('brigade') ? 'Just you for now' : null },
  ];
  const answered = lines.filter((l) => l.s !== step && (l.value !== null)).length;
  return (
    <aside className={styles.rail} aria-label="Setup ticket">
      <div className={styles.railBar} aria-hidden="true" />
      <div className={styles.ticket} style={{ viewTransitionName: 'larder-ticket' } as CSSProperties}>
        <span className={styles.clip} aria-hidden="true" />
        <p className={styles.ticketHead}><span>Larder · setup</span><span>No. 001</span></p>
        <dl className={styles.ticketLines}>
          {lines.map((l) => {
            const editing = l.s === step;
            const filled = !editing && l.value !== null;
            const flying = flight === l.s;
            return (
              <div key={l.s} className={styles.ticketLine} data-state={editing ? 'editing' : filled ? 'filled' : 'empty'}>
                <dt>{l.label}</dt>
                <dd>
                  {editing ? <span className={styles.ticketEditing}>answering now…</span>
                    : !filled ? <span className={styles.ticketEmpty}>—</span>
                      : l.items?.length ? (
                        <span className={styles.ticketItems}>{l.items.map((it) => <span key={it.key} style={fly(flying && it.key)}>{it.text}</span>)}</span>
                      ) : <span style={fly(flying && !l.items?.length && l.s)}>{l.value}</span>}
                </dd>
              </div>
            );
          })}
        </dl>
        <p className={styles.ticketFoot}><span>{step === 'done' ? 'Complete' : `${answered} of 5 answered`}</span><span>Sample workspace</span></p>
      </div>
    </aside>
  );
}

function Progress({ step }: { step: StepId }) {
  const cur = indexOf(step);
  return (
    <div className={styles.progress} role="group" aria-label="Setup progress" style={{ viewTransitionName: 'larder-progress' } as CSSProperties}>
      <ol>
        {STEPS.map((s, i) => {
          const state = i < cur ? 'done' : i === cur ? 'current' : 'todo';
          return (
            <li key={s.id} data-state={state} aria-current={state === 'current' ? 'step' : undefined}>
              <span className={styles.seg} aria-hidden="true" />
              <span className={styles.segLabel}>{s.short}<span className={styles.srOnly}>{state === 'done' ? ', done' : state === 'current' ? ', current step' : ', not started'}</span></span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

interface StepShellProps {
  n: number; question: ReactNode; why: string; headingRef: (el: HTMLHeadingElement | null) => void; uid: string;
  onSubmit: (e: FormEvent<HTMLFormElement>) => void; children: ReactNode; actions: ReactNode; onBack?: () => void;
}
function StepShell({ n, question, why, headingRef, uid, onSubmit, children, actions, onBack }: StepShellProps) {
  // Enter on a radio or checkbox advances, like Enter in a text field.
  const onKeyDown = (e: KeyboardEvent<HTMLFormElement>) => {
    const t = e.target as HTMLInputElement;
    if (e.key === 'Enter' && t.tagName === 'INPUT' && (t.type === 'radio' || t.type === 'checkbox')) { e.preventDefault(); e.currentTarget.requestSubmit(); }
  };
  return (
    <form className={styles.form} noValidate onSubmit={onSubmit} onKeyDown={onKeyDown} aria-labelledby={`${uid}q`}>
      {onBack ? (
        <button type="button" className={styles.back} onClick={onBack}>
          <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M10 3 5 8l5 5" /></svg>Back
        </button>
      ) : null}
      <h2 id={`${uid}q`} ref={headingRef} tabIndex={-1} className={styles.question}>
        <span className={styles.eyebrow}>{n <= 5 ? `Step ${n} of 5` : 'All set'}</span>
        <span className={styles.questionText}>{question}</span>
      </h2>
      <p className={styles.why}>{why}</p>
      <div className={styles.body}>{children}</div>
      <div className={styles.actions}>{actions}</div>
    </form>
  );
}

const wait = (ms: number) => new Promise<void>((r) => window.setTimeout(r, ms));
type Patch = Partial<Data> | ((d: Data) => Partial<Data>);

export default function AnimatedOnboarding() {
  const uid = useId();
  const { reduced } = useStudioMotion();
  const [step, setStep] = useState<StepId>('kitchen');
  const [data, setData] = useState<Data>(EMPTY);
  const [flight, setFlight] = useState<StepId | null>(null);
  const [failNext, setFailNext] = useState(false);
  const [ready, setReady] = useState(false);

  const stepRef = useRef(step); stepRef.current = step;
  const dataRef = useRef(data); dataRef.current = data;
  const reducedRef = useRef(reduced); reducedRef.current = reduced;
  const failRef = useRef(failNext); failRef.current = failNext;
  /** Demo switch: the next simulated request fails once, then the switch turns itself off. */
  const takeFailure = useCallback(() => { if (!failRef.current) return false; failRef.current = false; setFailNext(false); return true; }, []);
  const heading = useRef<HTMLHeadingElement | null>(null);
  const depth = useRef(0);
  const vtToken = useRef(0);
  const alive = useRef(true);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);

  const patch = useCallback((p: Patch) => setData((d) => ({ ...d, ...(typeof p === 'function' ? p(d) : p) })), []);

  /** One place that changes step: shared-element view transition, focus to the new heading. */
  const transitionTo = useCallback((next: StepId, dir: 'forward' | 'back', p?: Partial<Data>) => {
    const from = stepRef.current;
    const root = document.documentElement;
    const token = ++vtToken.current;
    root.dataset.larderDir = dir;
    root.dataset.larderVt = reducedRef.current ? 'fade' : 'move';
    const update = () => {
      flushSync(() => {
        if (p) setData((d) => ({ ...d, ...p }));
        setFlight(dir === 'forward' ? from : null);
        setStep(next);
      });
      const h = heading.current;
      if (h) {
        h.focus({ preventScroll: true });
        if (h.getBoundingClientRect().top < 56) h.scrollIntoView({ block: 'start' });
      }
    };
    void viewTransition(update).then(() => {
      if (token !== vtToken.current) return;
      delete root.dataset.larderDir;
      delete root.dataset.larderVt;
      if (alive.current) setFlight(null);
    });
  }, []);

  const goForward = useCallback((next: StepId, p?: Partial<Data>) => {
    depth.current += 1;
    window.history.pushState(null, '', hashFor(next));
    transitionTo(next, 'forward', p);
  }, [transitionTo]);

  const goBack = useCallback(() => {
    const prev = ORDER[indexOf(stepRef.current) - 1];
    if (!prev) return;
    if (depth.current > 0) { window.history.back(); return; } // popstate animates it
    window.history.replaceState(null, '', hashFor(prev));
    transitionTo(prev, 'back');
  }, [transitionTo]);

  // Restore: hash names the step, sessionStorage keeps the answers (resumable after reload or remount).
  useEffect(() => {
    const saved = load();
    const d = saved?.data ?? EMPTY;
    const wanted = stepFromHash(window.location.hash) ?? saved?.step ?? 'kitchen';
    const s = allowed(wanted, d);
    setData(d);
    setStep(s);
    if (stepFromHash(window.location.hash) !== s) window.history.replaceState(null, '', hashFor(s));
    setReady(true);
    const onPop = () => {
      const target = stepFromHash(window.location.hash);
      const cur = stepRef.current;
      if (!target || target === cur) return;
      const dir = indexOf(target) < indexOf(cur) ? 'back' : 'forward';
      depth.current = Math.max(0, depth.current + (dir === 'back' ? -1 : 1));
      transitionTo(allowed(target, dataRef.current), dir);
    };
    window.addEventListener('popstate', onPop);
    return () => {
      window.removeEventListener('popstate', onPop);
      delete document.documentElement.dataset.larderDir;
      delete document.documentElement.dataset.larderVt;
    };
  }, [transitionTo]);
  useEffect(() => { if (ready) save(step, data); }, [ready, step, data]);

  const restart = () => {
    clear();
    depth.current = 0;
    window.history.replaceState(null, '', hashFor('kitchen'));
    transitionTo('kitchen', 'back', { ...EMPTY });
  };

  const skip = (s: StepId, next: StepId, p: Partial<Data>) => goForward(next, { ...p, skipped: [...new Set([...dataRef.current.skipped, s])] });
  const setHeading = (el: HTMLHeadingElement | null) => { heading.current = el; };
  const shell = { uid, headingRef: setHeading };

  let panel: ReactNode = null;
  if (step === 'kitchen') panel = <KitchenStep key="kitchen" {...shell} data={data} patch={patch} onNext={(kitchen) => goForward('role', { kitchen })} />;
  if (step === 'role') panel = <RoleStep key="role" {...shell} data={data} patch={patch} onBack={goBack} onNext={() => goForward('goals', { skipped: data.skipped.filter((x) => x !== 'role') })} onSkip={() => skip('role', 'goals', { role: null })} />;
  if (step === 'goals') panel = <GoalsStep key="goals" {...shell} data={data} patch={patch} onBack={goBack} onNext={() => goForward('connect', { skipped: data.skipped.filter((x) => x !== 'goals') })} onSkip={() => skip('goals', 'connect', { goals: [] })} />;
  if (step === 'connect') panel = <ConnectStep key="connect" {...shell} data={data} patch={patch} reduced={reduced} takeFailure={takeFailure} onBack={goBack} onNext={() => goForward('brigade')} />;
  if (step === 'brigade') panel = <BrigadeStep key="brigade" {...shell} data={data} patch={patch} reduced={reduced} takeFailure={takeFailure} onBack={goBack} onSent={(invited) => goForward('done', { invited, skipped: data.skipped.filter((x) => x !== 'brigade') })} onSkip={() => skip('brigade', 'done', { invited: [] })} />;
  if (step === 'done') panel = <DoneStep key="done" {...shell} data={data} reduced={reduced} onRestart={restart} />;

  return (
    <div className={styles.root} data-reduced={reduced || undefined}>
      <style>{TRANSITION_CSS}</style>
      <header className={styles.top}>
        <p className={styles.brand}><span className={styles.mark} aria-hidden="true">L</span><span>Larder</span><span className={styles.brandSub}>Kitchen setup</span></p>
        <span className={styles.tag}>Sample workspace</span>
      </header>

      <div className={styles.main}>
        <section className={styles.flow} aria-label="Kitchen setup">
          <Progress step={step} />
          <div className={styles.panel} style={{ viewTransitionName: 'larder-step' } as CSSProperties}>{panel}</div>
        </section>
        <Ticket data={data} step={step} flight={flight} />
      </div>

      <footer className={styles.demoBar}>
        <fieldset className={styles.demoControls}>
          <legend>Demo controls <span>(not part of the product)</span></legend>
          <label className={styles.demoCheck}>
            <input type="checkbox" checked={failNext} onChange={(e) => setFailNext(e.currentTarget.checked)} />
            Make the next connection or invite fail
          </label>
          <button type="button" className={styles.textBtn} onClick={restart}>Start setup again</button>
        </fieldset>
        <p className={styles.fineprint}>Larder is a fictional product. Names, integrations and the prep list are sample content; nothing is sent anywhere.</p>
      </footer>
    </div>
  );
}

/* ── Steps ─────────────────────────────────────────────────────────────── */
type ShellBits = { uid: string; headingRef: (el: HTMLHeadingElement | null) => void };

function KitchenStep({ uid, headingRef, data, patch, onNext }: ShellBits & { data: Data; patch: (p: Patch) => void; onNext: (kitchen: string) => void }) {
  const [touched, setTouched] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const error = touched ? validateKitchen(data.kitchen) : null;
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const err = validateKitchen(data.kitchen);
    setTouched(true);
    if (err) { input.current?.focus(); return; }
    onNext(data.kitchen.trim());
  };
  return (
    <StepShell n={1} uid={uid} headingRef={headingRef} onSubmit={submit}
      question="What’s your kitchen called?" why="It names your workspace and heads every list Larder prints for the pass."
      actions={<button type="submit" className={styles.primary}>Continue<Arrow /></button>}>
      <div className={styles.field} data-invalid={error ? '' : undefined}>
        <label htmlFor={`${uid}kitchen`} className={styles.label}>Kitchen name</label>
        <div className={styles.inputWrap} style={fly(!error && data.kitchen.trim() && 'kitchen')}>
          <input
            ref={input} id={`${uid}kitchen`} className={styles.input} type="text" name="kitchen" autoComplete="organization" enterKeyHint="next"
            placeholder="e.g. The Gannet" value={data.kitchen} spellCheck={false}
            aria-invalid={error ? true : undefined} aria-describedby={`${uid}kitchen-err`}
            onChange={(e) => patch({ kitchen: e.currentTarget.value })}
            onBlur={() => { if (data.kitchen !== '') setTouched(true); }}
          />
        </div>
        <p id={`${uid}kitchen-err`} className={styles.error} aria-live="polite">{error ? <><Bang />{error}</> : null}</p>
      </div>
    </StepShell>
  );
}

function RoleStep({ uid, headingRef, data, patch, onNext, onBack, onSkip }: ShellBits & { data: Data; patch: (p: Patch) => void; onNext: () => void; onBack: () => void; onSkip: () => void }) {
  const [error, setError] = useState<string | null>(null);
  const first = useRef<HTMLInputElement>(null);
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!data.role) { setError('Choose the role closest to yours, or skip this step.'); first.current?.focus(); return; }
    onNext();
  };
  return (
    <StepShell n={2} uid={uid} headingRef={headingRef} onSubmit={submit} onBack={onBack}
      question="What’s your role there?" why="Larder opens on the view you’ll use most. You can switch views at any time."
      actions={<StepActions skip={<button type="button" className={styles.quiet} onClick={onSkip}>Skip for now</button>} />}>
      <fieldset className={styles.cards} aria-describedby={error ? `${uid}role-err` : undefined}>
        <legend className={styles.srOnly}>Your role</legend>
        {ROLES.map((r, i) => (
          <label key={r.id} className={styles.card} style={fly(data.role === r.id && 'role')}>
            <input ref={i === 0 ? first : undefined} className={styles.cardInput} type="radio" name={`${uid}role`} value={r.id} checked={data.role === r.id}
              onChange={() => { patch({ role: r.id }); setError(null); }} />
            <RoleIcon id={r.id} />
            <span className={styles.cardName}>{r.name}</span>
            <span className={styles.cardNote}>{r.note}</span>
          </label>
        ))}
      </fieldset>
      <p id={`${uid}role-err`} className={styles.error} aria-live="polite">{error ? <><Bang />{error}</> : null}</p>
    </StepShell>
  );
}

function GoalsStep({ uid, headingRef, data, patch, onNext, onBack, onSkip }: ShellBits & { data: Data; patch: (p: Patch) => void; onNext: () => void; onBack: () => void; onSkip: () => void }) {
  const [error, setError] = useState<string | null>(null);
  const first = useRef<HTMLInputElement>(null);
  const toggle = (id: GoalId, on: boolean) => {
    patch((d) => ({ goals: GOALS.map((g) => g.id).filter((g) => (g === id ? on : d.goals.includes(g))) }));
    if (on) setError(null);
  };
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!data.goals.length) { setError('Choose at least one list, or skip and Larder will start with prep lists.'); first.current?.focus(); return; }
    onNext();
  };
  return (
    <StepShell n={3} uid={uid} headingRef={headingRef} onSubmit={submit} onBack={onBack}
      question="What should Larder build first?" why="Pick one or more. We build these from tonight’s service, so they’re useful from tomorrow morning."
      actions={<StepActions skip={<button type="button" className={styles.quiet} onClick={onSkip}>Skip for now</button>} />}>
      <fieldset className={styles.cards} data-kind="goals" aria-describedby={error ? `${uid}goal-err` : undefined}>
        <legend className={styles.srOnly}>Lists to build first</legend>
        {GOALS.map((g, i) => {
          const on = data.goals.includes(g.id);
          return (
            <label key={g.id} className={styles.card} data-kind="check" style={fly(on && `goal-${g.id}`)}>
              <input ref={i === 0 ? first : undefined} className={styles.cardInput} type="checkbox" checked={on} aria-invalid={error ? true : undefined}
                onChange={(e) => toggle(g.id, e.currentTarget.checked)} />
              <span className={styles.tick} aria-hidden="true"><Check /></span>
              <span className={styles.cardName}>{g.name}</span>
              <span className={styles.cardNote}>{g.note}</span>
            </label>
          );
        })}
      </fieldset>
      <p id={`${uid}goal-err`} className={styles.error} aria-live="polite">{error ? <><Bang />{error}</> : null}</p>
    </StepShell>
  );
}

function ConnectStep({ uid, headingRef, data, patch, reduced, takeFailure, onNext, onBack }: ShellBits & {
  data: Data; patch: (p: Patch) => void; reduced: boolean; takeFailure: () => boolean; onNext: () => void; onBack: () => void;
}) {
  const [phase, setPhase] = useState<Record<IntegrationId, MorphPhase>>(() => ({
    till: data.connected.includes('till') ? 'success' : 'idle',
    suppliers: data.connected.includes('suppliers') ? 'success' : 'idle',
    calendar: data.connected.includes('calendar') ? 'success' : 'idle',
  }));
  const alive = useRef(true);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  const connect = async (id: IntegrationId) => {
    if (phase[id] === 'busy' || phase[id] === 'success') return;
    setPhase((p) => ({ ...p, [id]: 'busy' }));
    await wait(reduced ? 700 : 1300);
    if (!alive.current) return;
    if (takeFailure()) {
      setPhase((p) => ({ ...p, [id]: 'error' }));
      return;
    }
    setPhase((p) => ({ ...p, [id]: 'success' }));
    patch((d) => ({ connected: INTEGRATIONS.map((i) => i.id).filter((x) => x === id || d.connected.includes(x)) }));
  };
  const anyBusy = Object.values(phase).includes('busy');
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); if (!anyBusy) onNext(); };
  return (
    <StepShell n={4} uid={uid} headingRef={headingRef} onSubmit={submit} onBack={onBack}
      question="Connect your till and suppliers" why="Forecasts come from what you actually sell. Each connection says what it reads before you allow it. Optional: sample data works too."
      actions={<StepActions next={data.connected.length ? 'Continue' : 'Continue with sample data'} />}>
      <ul className={styles.integrations}>
        {INTEGRATIONS.map((it) => {
          const ph = phase[it.id];
          return (
            <li key={it.id} className={styles.integration} data-phase={ph}>
              <div className={styles.intText}>
                <p className={styles.intName}>{it.name} <span className={styles.intKind}>{it.note}</span></p>
                <p className={styles.intReads} id={`${uid}${it.id}-reads`}>{it.reads}</p>
                <p className={styles.intStatus} aria-live="polite" id={`${uid}${it.id}-status`}>
                  {ph === 'success' ? <span style={fly(`int-${it.id}`)} className={styles.okChip}><Check />Connected (simulated)</span>
                    : ph === 'error' ? <span className={styles.errText}><Bang />Couldn’t connect: the simulated service didn’t answer. Try again.</span>
                      : ph === 'busy' ? 'Connecting…' : 'Not connected'}
                </p>
              </div>
              <MorphButton size="s" reduced={reduced} phase={ph} onPress={() => void connect(it.id)} context={it.name}
                describedBy={`${uid}${it.id}-reads`}
                labels={{ idle: 'Connect', busy: 'Connecting…', success: 'Connected', error: 'Try again' }} />
            </li>
          );
        })}
      </ul>
    </StepShell>
  );
}

function BrigadeStep({ uid, headingRef, data, patch, reduced, takeFailure, onSent, onBack, onSkip }: ShellBits & {
  data: Data; patch: (p: Patch) => void; reduced: boolean; takeFailure: () => boolean; onSent: (emails: string[]) => void; onBack: () => void; onSkip: () => void;
}) {
  const nextKey = useRef(1);
  const [rows, setRows] = useState<{ key: number; value: string; touched: boolean }[]>(() =>
    (data.drafts.length ? data.drafts : data.invited.length ? data.invited : ['']).map((value) => ({ key: nextKey.current++, value, touched: false })));
  const [phase, setPhase] = useState<MorphPhase>('idle');
  const [formError, setFormError] = useState<string | null>(null);
  const list = useRef<HTMLUListElement>(null);
  const after = useRef<HTMLDivElement>(null);
  const inputs = useRef(new Map<number, HTMLInputElement>());
  const errRef = useRef<HTMLParagraphElement>(null);
  const alive = useRef(true);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  // Keep typed addresses in the flow's data so Back/Forward or a reload never loses them.
  const draft = rows.map((r) => r.value).join('\n');
  useEffect(() => { patch({ drafts: draft.split('\n') }); }, [draft, patch]);

  const errorOf = (i: number) => {
    const r = rows[i];
    return r.touched ? validateEmail(r.value, rows.filter((_, j) => j < i).map((x) => x.value)) : null;
  };
  /** FLIP the rows and everything under the list so adding/removing a row never jumps. */
  const reflow = (mutate: () => void) => {
    const els = [...(list.current?.querySelectorAll<HTMLElement>('[data-row]') ?? []), ...(after.current ? [after.current] : [])];
    flip(els, () => flushSync(mutate), { duration: D.base, reducedMotion: reduced });
  };
  const add = () => {
    const key = nextKey.current++;
    reflow(() => setRows((r) => [...r, { key, value: '', touched: false }]));
    requestAnimationFrame(() => {
      const el = inputs.current.get(key);
      el?.focus();
      if (el && !reduced && typeof el.animate === 'function') el.closest('li')?.animate([{ opacity: 0, transform: 'translateY(-6px)' }, { opacity: 1, transform: 'none' }], { duration: D.base, easing: cssEase('emphasized') });
    });
  };
  const remove = (key: number, i: number) => {
    reflow(() => setRows((r) => r.filter((x) => x.key !== key)));
    requestAnimationFrame(() => { const k = rows[i + 1]?.key ?? rows[i - 1]?.key; (k !== undefined ? inputs.current.get(k) : null)?.focus(); });
  };
  const submit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (phase === 'busy' || phase === 'success') return;
    const touchedRows = rows.map((r) => ({ ...r, touched: r.value !== '' || r.touched }));
    setRows(touchedRows);
    const errs = touchedRows.map((r, i) => (r.value.trim() ? validateEmail(r.value, touchedRows.filter((_, j) => j < i).map((x) => x.value)) : null));
    const firstBad = errs.findIndex(Boolean);
    if (firstBad >= 0) { inputs.current.get(touchedRows[firstBad].key)?.focus(); return; }
    const emails = touchedRows.map((r) => r.value.trim()).filter(Boolean);
    if (!emails.length) { setFormError('Add at least one email address, or choose Skip for now.'); inputs.current.get(touchedRows[0]?.key)?.focus(); return; }
    setFormError(null);
    setPhase('busy');
    await wait(reduced ? 700 : 1400);
    if (!alive.current) return;
    if (takeFailure()) {
      setPhase('error');
      setFormError('The invites didn’t send: the simulated server didn’t answer. Your list is kept; try again.');
      requestAnimationFrame(() => errRef.current?.focus());
      return;
    }
    setPhase('success');
    await wait(reduced ? 0 : 520);
    if (alive.current) onSent(emails);
  };
  return (
    <StepShell n={5} uid={uid} headingRef={headingRef} onSubmit={(e) => void submit(e)} onBack={onBack}
      question="Invite your brigade" why="Everyone you invite gets the prep list on their phone before service. They can join later too."
      actions={(
        <StepActions skip={<button type="button" className={styles.quiet} onClick={onSkip}>Skip for now</button>}
          primary={<MorphButton type="submit" reduced={reduced} phase={phase} describedBy={formError ? `${uid}inv-err` : undefined}
            labels={{ idle: 'Send invites', busy: 'Sending…', success: 'Invites sent', error: 'Try again' }} />} />
      )}>
      <ul ref={list} className={styles.invites} style={fly(phase !== 'idle' && phase !== 'error' && 'brigade')}>
        {rows.map((r, i) => {
          const err = errorOf(i);
          const id = `${uid}email${r.key}`;
          return (
            <li key={r.key} data-row className={styles.inviteRow} data-invalid={err ? '' : undefined}>
              <label htmlFor={id} className={styles.label}>{i === 0 ? 'Email address' : `Email address ${i + 1}`}</label>
              <div className={styles.inviteLine}>
                <input
                  ref={(el) => { if (el) inputs.current.set(r.key, el); else inputs.current.delete(r.key); }}
                  id={id} className={styles.input} type="email" inputMode="email" autoComplete="off" autoCapitalize="none" spellCheck={false} enterKeyHint="send"
                  placeholder="name@yourkitchen.co" value={r.value} readOnly={phase === 'busy' || phase === 'success'}
                  aria-invalid={err ? true : undefined} aria-describedby={`${id}-err`}
                  onChange={(e) => { const v = e.currentTarget.value; setRows((rs) => rs.map((x) => (x.key === r.key ? { ...x, value: v } : x))); setFormError(null); }}
                  onBlur={() => setRows((rs) => rs.map((x) => (x.key === r.key && x.value !== '' ? { ...x, touched: true } : x)))}
                />
                {rows.length > 1 ? (
                  <button type="button" className={styles.remove} onClick={() => remove(r.key, i)} aria-label={`Remove ${r.value.trim() || `email address ${i + 1}`}`}>
                    <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M4 4l8 8M12 4l-8 8" /></svg>
                  </button>
                ) : null}
              </div>
              <p id={`${id}-err`} className={styles.error} aria-live="polite">{err ? <><Bang />{err}</> : null}</p>
            </li>
          );
        })}
      </ul>
      <div ref={after} className={styles.afterList}>
        {rows.length < 4 ? <button type="button" className={styles.addRow} onClick={add} disabled={phase === 'busy'}>+ Add another</button> : <p className={styles.cardNote}>Four at a time; you can invite more from the team page.</p>}
        <p id={`${uid}inv-err`} ref={errRef} tabIndex={-1} className={styles.formError} aria-live="assertive">{formError ? <><Bang />{formError}</> : null}</p>
      </div>
    </StepShell>
  );
}

function DoneStep({ uid, headingRef, data, reduced, onRestart }: ShellBits & { data: Data; reduced: boolean; onRestart: () => void }) {
  const [loaded, setLoaded] = useState(false);
  const [opened, setOpened] = useState(false);
  const mark = useRef<SVGPathElement>(null);
  const ring = useRef<SVGCircleElement>(null);
  useEffect(() => {
    const t = window.setTimeout(() => setLoaded(true), reduced ? 500 : 950);
    return () => window.clearTimeout(t);
  }, [reduced]);
  useEffect(() => {
    // One brief celebration at the first outcome (≤ 1.2 s), removed under reduced motion.
    if (reduced) return;
    const a = [
      ring.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: D.slow, easing: cssEase('emphasized'), fill: 'both' }),
      mark.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: D.moderate, delay: D.base, easing: cssEase('emphasized'), fill: 'both' }),
    ];
    return () => { for (const x of a) x?.cancel(); };
  }, [reduced]);
  const kitchen = data.kitchen.trim() || 'Your kitchen';
  const tillNote = data.connected.includes('till') ? ' The till connection in this demo is simulated, so the figures are too.' : '';
  return (
    <StepShell n={6} uid={uid} headingRef={headingRef} onSubmit={(e) => { e.preventDefault(); setOpened(true); }}
      question={<>{kitchen} is set up.</>} why={`Here is the first thing Larder made for you: tomorrow’s prep list.${tillNote}`}
      actions={(
        <>
          <button type="submit" className={styles.primary}>Open the prep list<Arrow /></button>
          <button type="button" className={styles.quiet} onClick={onRestart}>Start again</button>
        </>
      )}>
      <svg className={styles.doneMark} viewBox="0 0 48 48" aria-hidden="true" focusable="false" data-static={reduced || undefined}>
        <circle ref={ring} cx="24" cy="24" r="21" pathLength={1} />
        <path ref={mark} d="m15 24.5 6.5 6.5L34 18" pathLength={1} />
      </svg>
      <section className={styles.prep} aria-labelledby={`${uid}prep`} aria-busy={!loaded}>
        <header className={styles.prepHead}>
          <h3 id={`${uid}prep`}>Prep list · tomorrow</h3>
          <span className={styles.tag}>Sample data</span>
        </header>
        <p className={styles.srOnly} role="status">{loaded ? 'Prep list ready: 5 items.' : 'Building tomorrow’s prep list…'}</p>
        {loaded ? (
          <ol className={styles.prepList} data-enter={!reduced || undefined}>
            {PREP_LIST.map((p) => (
              <li key={p.item}><span className={styles.prepItem}>{p.item}</span><span className={styles.prepFor}>{p.for}</span><span className={styles.prepQty}>{p.qty}</span></li>
            ))}
          </ol>
        ) : (
          <ol className={styles.skeleton} aria-hidden="true" data-shimmer={!reduced || undefined}>
            {PREP_LIST.map((p) => <li key={p.item}><span /><span /><span /></li>)}
          </ol>
        )}
      </section>
      {opened ? <p className={styles.endNote} role="status">Demo ends here. In Larder this opens the prep list for {kitchen}, sorted by section.</p> : null}
    </StepShell>
  );
}

function StepActions({ skip, next = 'Continue', primary }: { skip?: ReactNode; next?: string; primary?: ReactNode }) {
  return (
    <>
      {primary ?? <button type="submit" className={styles.primary}>{next}<Arrow /></button>}
      {skip}
    </>
  );
}

function Arrow() {
  return <svg className={styles.arrow} viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 8h9.5M8.5 4l4 4-4 4" /></svg>;
}

/** Larder — fictional kitchen prep & ordering app. All names, copy and the prep list are sample content. */

export type StepId = 'kitchen' | 'role' | 'goals' | 'connect' | 'brigade' | 'done';
export type RoleId = 'head-chef' | 'owner' | 'sous-chef' | 'manager';
export type GoalId = 'prep' | 'orders' | 'waste' | 'allergens';
export type IntegrationId = 'till' | 'suppliers' | 'calendar';

export const STEPS: { id: Exclude<StepId, 'done'>; short: string }[] = [
  { id: 'kitchen', short: 'Kitchen' },
  { id: 'role', short: 'Role' },
  { id: 'goals', short: 'First lists' },
  { id: 'connect', short: 'Connect' },
  { id: 'brigade', short: 'Brigade' },
];
export const ORDER: StepId[] = ['kitchen', 'role', 'goals', 'connect', 'brigade', 'done'];
export const indexOf = (s: StepId) => ORDER.indexOf(s);

export const ROLES: { id: RoleId; name: string; note: string }[] = [
  { id: 'head-chef', name: 'Head chef', note: 'Opens on tomorrow’s prep and the order sheet.' },
  { id: 'owner', name: 'Owner', note: 'Opens on food cost and supplier spend.' },
  { id: 'sous-chef', name: 'Sous chef', note: 'Opens on the prep list for your section.' },
  { id: 'manager', name: 'Kitchen manager', note: 'Opens on stock counts and deliveries.' },
];

export const GOALS: { id: GoalId; name: string; note: string }[] = [
  { id: 'prep', name: 'Prep lists', note: 'What to make tomorrow, scaled to the bookings.' },
  { id: 'orders', name: 'Supplier orders', note: 'Order sheets from your par levels, ready by close.' },
  { id: 'waste', name: 'Waste log', note: 'What gets binned and why, tallied by the week.' },
  { id: 'allergens', name: 'Allergen sheet', note: 'Every dish against the 14 allergens, kept current.' },
];

export const INTEGRATIONS: { id: IntegrationId; name: string; note: string; reads: string }[] = [
  { id: 'till', name: 'Your till', note: 'Point of sale', reads: 'Reads covers and dishes sold, never card details.' },
  { id: 'suppliers', name: 'Supplier price lists', note: 'Emailed or uploaded', reads: 'Reads pack sizes and prices to cost each order.' },
  { id: 'calendar', name: 'Bookings calendar', note: 'Shared calendar', reads: 'Reads booking counts and private events.' },
];

export const PREP_LIST: { item: string; qty: string; for: string }[] = [
  { item: 'Shallots, brunoise', qty: '1.2 kg', for: 'Three dishes' },
  { item: 'Chicken stock', qty: '8 L', for: 'Sauce base, risotto' },
  { item: 'Pickled rhubarb', qty: '2 jars', for: 'Mackerel starter' },
  { item: 'Brown butter', qty: '600 g', for: 'Hake, cauliflower' },
  { item: 'Focaccia dough', qty: '2 trays', for: 'Bread service' },
];

export interface Data {
  kitchen: string;
  role: RoleId | null;
  goals: GoalId[];
  connected: IntegrationId[];
  invited: string[];
  /** Invite addresses typed but not yet sent, kept so Back/Forward or a reload never loses them. */
  drafts: string[];
  skipped: StepId[];
}
export const EMPTY: Data = { kitchen: '', role: null, goals: [], connected: [], invited: [], drafts: [], skipped: [] };

/* ── Validation (messages say how to fix) ─────────────────────────────── */
export function validateKitchen(v: string): string | null {
  const t = v.trim();
  if (!t) return 'Enter your kitchen’s name, the way your team says it.';
  if (t.length < 2) return 'Use at least 2 characters, for example “The Gannet”.';
  if (t.length > 40) return `Keep it to 40 characters or fewer (now ${t.length}). You can add the full name later.`;
  return null;
}
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
export function validateEmail(v: string, others: string[]): string | null {
  const t = v.trim();
  if (!t) return null;
  if (!EMAIL.test(t)) return 'Enter an email address like sam@yourkitchen.co.';
  if (others.some((o) => o.trim().toLowerCase() === t.toLowerCase())) return 'You’ve already added this address.';
  return null;
}

/* ── Persistence: the hash names the step, sessionStorage keeps the answers ─ */
export const STORAGE_KEY = 'maquettekit:larder-onboarding';
export const hashFor = (s: StepId) => `#larder-step=${s}`;
export function stepFromHash(hash: string): StepId | null {
  const m = /larder-step=([a-z]+)/.exec(hash);
  return m && (ORDER as string[]).includes(m[1]) ? (m[1] as StepId) : null;
}
export function load(): { step: StepId; data: Data } | null {
  try {
    const raw = window.sessionStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const v = JSON.parse(raw) as { step?: StepId; data?: Partial<Data> };
    return { step: v.step && ORDER.includes(v.step) ? v.step : 'kitchen', data: { ...EMPTY, ...v.data } };
  } catch { return null; }
}
export function save(step: StepId, data: Data): void {
  try { window.sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ step, data })); } catch { /* private mode: state just won't survive reload */ }
}
export function clear(): void {
  try { window.sessionStorage.removeItem(STORAGE_KEY); } catch { /* ignore */ }
}
/** The furthest step the answers allow (the kitchen name is the only hard requirement). */
export const allowed = (s: StepId, d: Data): StepId => (indexOf(s) > 0 && validateKitchen(d.kitchen) ? 'kitchen' : s);

'use client';
/**
 * Async submit button — the morph-submit-button recipe's choreography (pill → circle with a decelerating arc →
 * check or "!" → pill), re-implemented as a controlled component: the recipe is a sealed waitlist card with its own
 * copy and email field, while this flow needs the parent to own the request and the phase.
 */
import { useEffect, useRef, type CSSProperties } from 'react';
import { cssEase, duration as D, useIsomorphicLayoutEffect } from '../../../motion';
import styles from './styles.module.css';

export type MorphPhase = 'idle' | 'busy' | 'success' | 'error';

interface Props {
  phase: MorphPhase;
  labels: Record<MorphPhase, string>;
  reduced: boolean;
  type?: 'button' | 'submit';
  size?: 'm' | 's';
  onPress?: () => void;
  describedBy?: string;
  /** Accessible name suffix, e.g. the integration name, kept out of the visible label. */
  context?: string;
}

const HOLD = 620;

export function MorphButton({ phase, labels, reduced, type = 'button', size = 'm', onPress, describedBy, context }: Props) {
  const slot = useRef<HTMLSpanElement>(null);
  const btn = useRef<HTMLButtonElement>(null);
  const label = useRef<HTMLSpanElement>(null);
  const ring = useRef<SVGSVGElement>(null);
  const arc = useRef<SVGCircleElement>(null);
  const check = useRef<SVGPathElement>(null);
  const bang = useRef<SVGGElement>(null);
  const live = useRef<Partial<Record<'width' | 'label' | 'ring' | 'arc' | 'mark' | 'shake', Animation>>>({});
  const timers = useRef(new Set<number>());
  const settled = useRef(true);

  const stop = (k: keyof typeof live.current) => { live.current[k]?.cancel(); delete live.current[k]; };
  const play = (k: keyof typeof live.current, el: Element | null, kf: Keyframe[], o: KeyframeAnimationOptions) => {
    if (!el || typeof el.animate !== 'function') return null;
    const a = el.animate(kf, o);
    live.current[k] = a;
    return a;
  };
  const opacityOf = (el: Element | null) => (el ? Number(getComputedStyle(el).opacity) : 1);
  const later = (ms: number, fn: () => void) => { const t = window.setTimeout(() => { timers.current.delete(t); fn(); }, ms); timers.current.add(t); };

  useEffect(() => {
    const t = timers.current, l = live.current;
    return () => { for (const id of t) window.clearTimeout(id); for (const a of Object.values(l)) a?.cancel(); };
  }, []);

  useIsomorphicLayoutEffect(() => {
    for (const id of timers.current) window.clearTimeout(id);
    timers.current.clear();
    const b = btn.current, s = slot.current;
    if (!b || !s) return;
    const btnEl = b, slotEl = s;
    if (reduced || phase === 'idle') {
      for (const k of Object.keys(live.current) as (keyof typeof live.current)[]) stop(k);
      settled.current = true;
      btnEl.dataset.settled = 'true';
      return;
    }
    const emph = cssEase('emphasized');
    const toCircle = () => {
      const from = btnEl.getBoundingClientRect().width, h = btnEl.getBoundingClientRect().height;
      stop('width');
      play('width', btnEl, [{ width: `${from}px` }, { width: `${h}px` }], { duration: D.moderate, easing: emph, fill: 'forwards' });
    };
    const toPill = () => {
      const from = btnEl.getBoundingClientRect().width, to = slotEl.getBoundingClientRect().width;
      stop('width');
      const a = play('width', btnEl, [{ width: `${from}px` }, { width: `${to}px` }], { duration: D.moderate, easing: emph, fill: 'forwards' });
      a?.finished.then(() => { if (live.current.width === a) stop('width'); }, () => {});
      const o = opacityOf(label.current);
      stop('label');
      play('label', label.current, [{ opacity: o, transform: 'translateY(4px)' }, { opacity: 1, transform: 'none' }], { duration: D.base, delay: D.moderate * 0.4, easing: emph, fill: 'both' });
      settled.current = true;
      btnEl.dataset.settled = 'true';
    };

    if (phase === 'busy') {
      settled.current = false;
      delete btnEl.dataset.settled;
      const o = opacityOf(label.current);
      stop('label'); stop('mark'); stop('shake');
      play('label', label.current, [{ opacity: o }, { opacity: 0 }], { duration: D.fast, easing: 'linear', fill: 'forwards' });
      toCircle();
      stop('ring'); stop('arc');
      play('ring', ring.current, [{ opacity: 0, transform: 'scale(0.6)' }, { opacity: 1, transform: 'scale(1)' }], { duration: D.base, delay: D.moderate * 0.5, easing: emph, fill: 'both' });
      // A decelerating arc that never completes on its own: progress without a fake percentage or an infinite spin.
      play('arc', arc.current, [{ strokeDashoffset: 1 }, { strokeDashoffset: 0.1 }], { duration: 2400, delay: D.moderate * 0.5, easing: cssEase('enter'), fill: 'both' });
      return;
    }

    const at = arc.current ? parseFloat(getComputedStyle(arc.current).strokeDashoffset) || 0 : 0;
    stop('arc');
    if (phase === 'success') {
      play('arc', arc.current, [{ strokeDashoffset: at }, { strokeDashoffset: 0 }], { duration: D.fast, easing: cssEase('standard'), fill: 'forwards' });
      later(D.fast, () => {
        const ro = opacityOf(ring.current);
        stop('ring');
        play('ring', ring.current, [{ opacity: ro }, { opacity: 0 }], { duration: D.base, easing: 'linear', fill: 'forwards' });
        play('mark', check.current, [{ strokeDashoffset: 1, opacity: 1 }, { strokeDashoffset: 0, opacity: 1 }], { duration: D.moderate, delay: 60, easing: emph, fill: 'both' });
      });
    } else {
      play('arc', arc.current, [{ strokeDashoffset: at }, { strokeDashoffset: at }], { duration: 1, fill: 'forwards' });
      const ro = opacityOf(ring.current);
      stop('ring');
      play('ring', ring.current, [{ opacity: ro }, { opacity: 0 }], { duration: D.base, easing: 'linear', fill: 'forwards' });
      play('mark', bang.current, [{ strokeDashoffset: 1, opacity: 1 }, { strokeDashoffset: 0, opacity: 1 }], { duration: D.moderate, delay: 40, easing: emph, fill: 'both' });
      play('shake', btnEl, [
        { transform: 'translateX(0)' }, { transform: 'translateX(-6px)' }, { transform: 'translateX(5px)' },
        { transform: 'translateX(-3px)' }, { transform: 'translateX(2px)' }, { transform: 'translateX(0)' },
      ], { duration: 440, delay: 60, easing: 'ease-out' });
    }
    later(HOLD, () => {
      const mo = opacityOf(phase === 'success' ? check.current : bang.current);
      stop('mark');
      play('mark', phase === 'success' ? check.current : bang.current, [{ opacity: mo }, { opacity: 0 }], { duration: D.fast, easing: 'linear', fill: 'forwards' });
      toPill();
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, reduced]);

  const locked = phase === 'busy' || phase === 'success';
  return (
    <span ref={slot} className={styles.morphSlot} data-size={size}>
      <span className={styles.morphSizer} aria-hidden="true">
        {(['idle', 'busy', 'success', 'error'] as const).map((p) => <span key={p}>{p === 'success' ? <><Check />{labels[p]}</> : labels[p]}</span>)}
      </span>
      <button
        ref={btn}
        type={type}
        className={styles.morph}
        data-phase={phase}
        data-size={size}
        aria-busy={phase === 'busy' || undefined}
        aria-disabled={locked || undefined}
        aria-describedby={describedBy}
        onClick={(e) => { if (locked) { e.preventDefault(); return; } onPress?.(); }}
        style={{ '--morph': `${D.moderate}ms` } as CSSProperties}
      >
        <span ref={label} className={styles.morphLabel}>
          {phase === 'success' ? <Check /> : null}
          {labels[phase]}
          {context ? <span className={styles.srOnly}> {context}</span> : null}
        </span>
        <svg ref={ring} className={styles.morphRing} viewBox="0 0 24 24" aria-hidden="true" focusable="false">
          <circle className={styles.morphTrack} cx="12" cy="12" r="9.5" />
          <circle ref={arc} className={styles.morphArc} cx="12" cy="12" r="9.5" pathLength={1} transform="rotate(-90 12 12)" />
        </svg>
        <svg className={styles.morphMark} viewBox="0 0 24 24" aria-hidden="true" focusable="false">
          <path ref={check} className={styles.morphStroke} d="m7 12.5 3.4 3.4L17.2 8.6" pathLength={1} />
          <g ref={bang} className={styles.morphBang}>
            <path className={styles.morphStroke} d="M12 6.75v6.5" pathLength={1} />
            <path className={styles.morphDot} d="M12 17.25h.01" />
          </g>
        </svg>
      </button>
    </span>
  );
}

export function Check({ className }: { className?: string }) {
  return (
    <svg className={className ?? styles.inlineCheck} viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
      <path d="m3.5 8.5 3 3 6-6.5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/* Larder — kitchen setup.
   The questions speak in a menu's serif; the answers land on a thermal ticket clipped to the pass rail (mono, torn
   edge, one soft shadow — the only elevated object). Pill buttons, signal colour for the single primary action. */

.root {
  display: flex;
  flex-direction: column;
  min-height: calc(100dvh - 44px);
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  overflow-x: clip;
}
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

/* ── Header ────────────────────────────────────────────────────────────── */
.top { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px; border-bottom: 1px solid var(--mk-line, #11110f24); }
.brand { display: flex; align-items: center; gap: 10px; margin: 0; font-family: var(--mk-font-display, ui-sans-serif, sans-serif); font-weight: 700; font-size: 1.125rem; letter-spacing: -0.02em; }
.mark { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 7px; background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); font-size: 0.9375rem; }
.brandSub { padding-left: 10px; border-left: 1px solid var(--mk-line, #11110f24); font-family: var(--mk-font-mono, ui-monospace, monospace); font-weight: 400; font-size: 0.6875rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.tag { flex: none; padding: 3px 9px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; }
@container (min-width: 900px) { .top { padding-inline: 40px; } }

/* ── Layout ────────────────────────────────────────────────────────────── */
.main { flex: 1; display: grid; grid-template-columns: minmax(0, 1fr); gap: 48px; align-items: start; width: 100%; max-width: 1180px; margin: 0 auto; padding: 22px 16px 48px; }
.flow { min-width: 0; }
@container (min-width: 900px) {
  .main { grid-template-columns: minmax(0, 1fr) 330px; gap: clamp(56px, 7cqi, 112px); padding: 44px 40px 72px; }
  .rail { position: sticky; top: 84px; }
}

/* ── Progress ──────────────────────────────────────────────────────────── */
.progress ol { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; margin: 0 0 clamp(26px, 5cqi, 52px); padding: 0; list-style: none; }
.progress li { display: grid; gap: 8px; }
.seg { position: relative; height: 4px; border-radius: 2px; overflow: hidden; background: var(--mk-surface-2, #e9e5da); }
.seg::after { content: ''; position: absolute; inset: 0; background: var(--mk-ink, #11110f); transform: scaleX(0); transform-origin: left center; }
.progress li[data-state='done'] .seg::after { transform: scaleX(1); }
.progress li[data-state='current'] .seg::after { transform: scaleX(1); background: var(--mk-signal, #bf2f09); }
.segLabel { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.progress li[data-state='current'] .segLabel { color: var(--mk-ink, #11110f); }
@container (max-width: 599px) { .segLabel { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); } }
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .seg::after { transition: transform var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease), background-color var(--mk-duration-base, 240ms); }
}

/* ── Step shell ────────────────────────────────────────────────────────── */
.form { display: block; }
.back {
  display: inline-flex; align-items: center; gap: 6px; min-height: 36px; margin: -6px 0 14px -10px; padding: 4px 10px;
  border: 0; border-radius: 999px; background: none; color: var(--mk-ink-muted, #5c5a52); cursor: pointer;
  font: 500 0.875rem/1 var(--mk-font-text, ui-sans-serif, sans-serif);
}
.back svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.back:hover { color: var(--mk-ink, #11110f); background: var(--mk-surface-2, #e9e5da); }
.question { display: grid; gap: 14px; margin: 0; border-radius: 4px; }
.question:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 8px; }
.eyebrow { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 400; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mk-signal, #bf2f09); }
.questionText {
  max-width: 15ch; font-family: var(--mk-font-serif, Georgia, serif); font-weight: 400;
  font-size: clamp(2.5rem, 1.5rem + 3.6cqi, 4.25rem); line-height: 1; letter-spacing: -0.015em; text-wrap: balance;
}
.why { max-width: 50ch; margin: 18px 0 0; font-size: 1rem; line-height: 1.55; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }
.body { margin-top: clamp(26px, 4cqi, 40px); }
.actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 32px; }

/* ── Buttons ───────────────────────────────────────────────────────────── */
.primary, .quiet {
  display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 52px; padding: 0 24px;
  border-radius: 999px; cursor: pointer; font: 600 1rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); white-space: nowrap;
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}
.primary { border: 0; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); padding-right: 20px; }
.primary:hover { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 86%, #000); }
.quiet { border: 1.5px solid var(--mk-line-strong, #11110f); background: transparent; color: var(--mk-ink, #11110f); }
.quiet:hover { background: var(--mk-surface-2, #e9e5da); }
.primary:active, .quiet:active { transform: scale(0.98); }
.primary:focus-visible, .quiet:focus-visible, .back:focus-visible, .remove:focus-visible, .addRow:focus-visible, .textBtn:focus-visible, .morph:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }
.arrow { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: transform var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease); }
.primary:hover .arrow { transform: translateX(3px); }
.textBtn { min-height: 32px; padding: 4px 2px; border: 0; background: none; color: var(--mk-ink, #11110f); cursor: pointer; font: 500 0.875rem/1.3 var(--mk-font-text, ui-sans-serif, sans-serif); text-decoration: underline; text-underline-offset: 3px; }
@container (max-width: 479px) {
  .actions > .primary, .actions > .morphSlot { flex: 1 1 100%; }
  .actions > .morphSlot .morph { width: 100%; }
  .actions > .quiet { flex: 1 1 100%; }
}

/* ── Text field ────────────────────────────────────────────────────────── */
.field { display: grid; gap: 8px; max-width: 480px; }
.label { font-size: 0.875rem; font-weight: 600; }
.inputWrap { display: block; border-radius: 12px; }
.input {
  width: 100%; min-height: 54px; padding: 12px 16px; border: 1.5px solid var(--mk-ink-muted, #5c5a52); border-radius: 12px;
  background: var(--mk-surface, #fbf9f4); color: var(--mk-ink, #11110f); font: 1.125rem/1.3 var(--mk-font-text, ui-sans-serif, sans-serif);
  transition: border-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.input::placeholder { color: var(--mk-ink-muted, #5c5a52); opacity: 1; }
.input:hover { border-color: var(--mk-ink, #11110f); }
.input:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; border-color: var(--mk-ink, #11110f); }
.input[aria-invalid='true'] { border-color: var(--mk-danger, #b42318); border-width: 2px; }
.input[readonly] { background: var(--mk-surface-2, #e9e5da); }
.error, .formError { display: flex; gap: 7px; align-items: flex-start; margin: 0; min-height: 1.4em; font-size: 0.875rem; line-height: 1.4; color: var(--mk-danger, #b42318); }
.formError { margin-top: 14px; min-height: 0; border-radius: 4px; }
.formError:empty { margin: 0; }
.formError:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; }
.errIcon { flex: none; width: 16px; height: 16px; margin-top: 1px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }

/* ── Choice cards ──────────────────────────────────────────────────────── */
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15.5rem), 1fr)); gap: 10px; min-inline-size: 0; margin: 0 0 8px; padding: 0; border: 0; max-width: 640px; }
.card {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: 14px; row-gap: 4px; align-items: start;
  min-height: 92px; padding: 16px 40px 16px 16px; border: 1.5px solid var(--mk-line, #11110f24); border-radius: 14px;
  background: var(--mk-surface, #fbf9f4); cursor: pointer;
  transition: border-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), transform var(--mk-duration-instant, 90ms) var(--mk-ease-standard, ease);
}
.card:hover { border-color: var(--mk-ink-muted, #5c5a52); }
.card:active { transform: scale(0.992); }
.card:has(:checked) { border-color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 1px var(--mk-ink, #11110f); }
.card:has(:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.card:not([data-kind])::after { content: ''; position: absolute; top: 16px; right: 16px; width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid var(--mk-ink-muted, #5c5a52); }
.card:not([data-kind]):has(:checked)::after { border-color: var(--mk-ink, #11110f); background: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 2.5px var(--mk-surface, #fbf9f4); }
.cardInput { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.roleIcon { grid-row: span 2; width: 28px; height: 28px; margin-top: 1px; color: var(--mk-ink, #11110f); }
.cardName { font-weight: 600; font-size: 1rem; line-height: 1.3; }
.cardNote { grid-column: 2; font-size: 0.875rem; line-height: 1.4; color: var(--mk-ink-muted, #5c5a52); }
.tick { grid-row: span 2; display: grid; place-items: center; width: 22px; height: 22px; margin-top: 1px; border: 1.5px solid var(--mk-ink-muted, #5c5a52); border-radius: 6px; color: var(--mk-bg, #f3f0e8); }
.tick svg { width: 15px; height: 15px; opacity: 0; }
.card:has(:checked) .tick { background: var(--mk-ink, #11110f); border-color: var(--mk-ink, #11110f); }
.card:has(:checked) .tick svg { opacity: 1; }
.card[data-kind] { padding-right: 16px; }

/* ── Integrations ──────────────────────────────────────────────────────── */
.integrations { display: grid; max-width: 640px; margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--mk-line, #11110f24); }
.integration { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 18px 0; border-bottom: 1px solid var(--mk-line, #11110f24); }
.intText { min-width: 0; }
.intName { margin: 0; font-weight: 600; }
.intKind { margin-left: 6px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 400; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.intReads { margin: 4px 0 0; font-size: 0.875rem; line-height: 1.4; color: var(--mk-ink-muted, #5c5a52); }
.intStatus { margin: 8px 0 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.02em; color: var(--mk-ink-muted, #5c5a52); }
.okChip { display: inline-flex; align-items: center; gap: 5px; color: var(--mk-success, #0a6e4d); }
.okChip svg { width: 14px; height: 14px; }
.errText { display: inline-flex; gap: 6px; color: var(--mk-danger, #b42318); font-family: var(--mk-font-text, ui-sans-serif, sans-serif); font-size: 0.8125rem; }

/* ── Invites ───────────────────────────────────────────────────────────── */
.invites { display: grid; gap: 2px; max-width: 520px; margin: 0; padding: 0; list-style: none; border-radius: 12px; }
.inviteRow { display: grid; gap: 6px; }
.inviteLine { display: flex; align-items: center; gap: 8px; }
.remove { flex: none; display: grid; place-items: center; width: 48px; height: 48px; border: 1px solid var(--mk-line, #11110f24); border-radius: 12px; background: transparent; color: var(--mk-ink, #11110f); cursor: pointer; }
.remove:hover { background: var(--mk-surface-2, #e9e5da); }
.remove svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
.afterList { max-width: 520px; }
.addRow { min-height: 44px; padding: 8px 16px; border: 1.5px dashed var(--mk-ink-muted, #5c5a52); border-radius: 999px; background: transparent; color: var(--mk-ink, #11110f); font: 600 0.9375rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); cursor: pointer; }
.addRow:hover { border-style: solid; }
.addRow:disabled { cursor: not-allowed; color: var(--mk-ink-muted, #5c5a52); }

/* ── Morphing async button (morph-submit-button choreography) ──────────── */
.morphSlot { display: inline-grid; vertical-align: middle; }
.morphSizer { grid-area: 1 / 1; display: grid; visibility: hidden; pointer-events: none; }
.morphSizer > span, .morphLabel { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 0 24px; white-space: nowrap; font: 600 1rem/1 var(--mk-font-text, ui-sans-serif, sans-serif); }
.morphSizer > span { grid-area: 1 / 1; min-height: 52px; }
.morph {
  grid-area: 1 / 1; justify-self: start; position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: 100%; min-height: 52px; padding: 0; overflow: hidden; border: 0; border-radius: 999px;
  background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); cursor: pointer;
  transition: background-color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease), color var(--mk-duration-base, 240ms);
}
.morph:hover:not([aria-disabled]) { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 86%, #000); }
.morph[data-size='s'], .morphSlot[data-size='s'] .morphSizer > span { min-height: 42px; }
.morphSlot[data-size='s'] .morphSizer > span, .morph[data-size='s'] .morphLabel { padding: 0 18px; font-size: 0.875rem; }
.morph[data-size='s'] { background: transparent; color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 1.5px var(--mk-ink, #11110f); }
.morph[data-size='s']:hover:not([aria-disabled]) { background: var(--mk-surface-2, #e9e5da); }
.morph[data-phase='success'] { background: var(--mk-success, #0a6e4d); color: var(--mk-bg, #f3f0e8); box-shadow: none; }
.morph[data-phase='error']:not([data-settled]) { background: var(--mk-danger, #b42318); color: var(--mk-bg, #f3f0e8); box-shadow: none; }
.morph[aria-disabled='true'] { cursor: progress; }
.morph[data-phase='success'][aria-disabled='true'] { cursor: default; }
.morphRing, .morphMark { position: absolute; top: 50%; left: 50%; width: 24px; height: 24px; margin: -12px 0 0 -12px; overflow: visible; pointer-events: none; }
.morphRing { opacity: 0; }
.morphTrack { fill: none; stroke: currentColor; stroke-opacity: 0.32; stroke-width: 2.4; }
.morphArc { fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; }
.morphStroke { fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1; }
.morphBang { opacity: 0; }
.morphBang .morphStroke { stroke-dashoffset: 0; }
.morphDot { fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: round; }
.inlineCheck { flex: none; width: 16px; height: 16px; }

/* ── Ticket on the rail ────────────────────────────────────────────────── */
.rail { position: relative; padding-top: 22px; }
.railBar { position: absolute; top: 0; left: -16px; right: -16px; height: 5px; border-radius: 3px; background: var(--mk-ink, #11110f); box-shadow: inset 0 1px 0 color-mix(in oklab, var(--mk-bg, #f3f0e8) 35%, transparent); }
.ticket {
  position: relative; max-width: 340px; margin: 0 auto 10px; padding: 30px 22px 24px;
  background: var(--mk-surface, #fbf9f4); color: var(--mk-ink, #11110f); font-family: var(--mk-font-mono, ui-monospace, monospace);
  transform: rotate(-0.8deg); transform-origin: 50% 0;
  filter: drop-shadow(0 0 0.5px var(--mk-line-strong, #11110f)) drop-shadow(0 12px 18px rgb(0 0 0 / 0.1));
}
.ticket::after { content: ''; position: absolute; left: 0; right: 0; bottom: -8px; height: 8px; background: conic-gradient(from -45deg at 50% 100%, var(--mk-surface, #fbf9f4) 90deg, transparent 0) 0 0 / 14px 8px repeat-x; }
.clip { position: absolute; top: -26px; left: 50%; width: 46px; height: 34px; margin-left: -23px; border-radius: 5px 5px 3px 3px; background: var(--mk-ink, #11110f); }
.clip::after { content: ''; position: absolute; left: 9px; right: 9px; bottom: 7px; height: 2px; border-radius: 1px; background: var(--mk-bg, #f3f0e8); }
.ticketHead, .ticketFoot { display: flex; justify-content: space-between; gap: 12px; margin: 0; font-size: 0.6875rem; letter-spacing: 0.1em; text-transform: uppercase; }
.ticketHead { padding-bottom: 12px; border-bottom: 1px dashed var(--mk-ink-muted, #5c5a52); }
.ticketFoot { margin-top: 14px; color: var(--mk-ink-muted, #5c5a52); }
.ticketLines { margin: 0; }
.ticketLine { display: grid; grid-template-columns: 6.25rem minmax(0, 1fr); gap: 10px; padding: 11px 0; border-bottom: 1px dotted var(--mk-ink-muted, #5c5a52); }
.ticketLine dt { padding-top: 2px; font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.ticketLine dd { margin: 0; font-size: 0.875rem; line-height: 1.35; overflow-wrap: anywhere; }
.ticketItems { display: grid; gap: 3px; }
.ticketItems > span, .ticketLine dd > span { display: inline-block; }
.ticketEditing { color: var(--mk-signal, #bf2f09); }
.ticketEmpty { color: var(--mk-ink-muted, #5c5a52); }

/* ── Done ──────────────────────────────────────────────────────────────── */
.doneMark { display: block; width: 56px; height: 56px; margin-bottom: 18px; }
.doneMark circle, .doneMark path { fill: none; stroke: var(--mk-success, #0a6e4d); stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1; }
.prep { max-width: 560px; padding: 18px 20px 6px; border: 1px solid var(--mk-line, #11110f24); border-radius: 16px; background: var(--mk-surface, #fbf9f4); }
.prepHead { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.prepHead h3 { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, sans-serif); font-size: 1.125rem; font-weight: 700; letter-spacing: -0.01em; }
.prepList, .skeleton { margin: 10px 0 0; padding: 0; list-style: none; }
.prepList li, .skeleton li { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: 16px; align-content: center; min-height: 68px; padding: 10px 0; border-top: 1px solid var(--mk-line, #11110f24); }
.prepItem { font-weight: 600; }
.prepFor { grid-column: 1; font-size: 0.8125rem; color: var(--mk-ink-muted, #5c5a52); }
.prepQty { grid-column: 2; grid-row: 1 / span 2; align-self: center; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.9375rem; font-variant-numeric: tabular-nums; }
.skeleton span { display: block; height: 12px; border-radius: 6px; background: var(--mk-surface-2, #e9e5da); }
.skeleton span:nth-child(1) { width: 58%; margin-bottom: 8px; }
.skeleton span:nth-child(2) { grid-column: 1; width: 36%; height: 10px; }
.skeleton span:nth-child(3) { grid-column: 2; grid-row: 1 / span 2; align-self: center; width: 52px; }
.skeleton[data-shimmer] span {
  background: linear-gradient(90deg, var(--mk-surface-2, #e9e5da) 30%, color-mix(in oklab, var(--mk-surface-2, #e9e5da) 55%, var(--mk-surface, #fbf9f4)) 50%, var(--mk-surface-2, #e9e5da) 70%) 0 0 / 300% 100%;
  animation: ld-shimmer 1.5s linear infinite;
}
@keyframes ld-shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }
.prepList[data-enter] { animation: ld-in var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease) both; }
@keyframes ld-in { from { opacity: 0; } }
.endNote { max-width: 560px; margin: 16px 0 0; padding: 12px 14px; border-left: 2px solid var(--mk-ink, #11110f); background: var(--mk-surface, #fbf9f4); font-size: 0.9375rem; line-height: 1.45; }

/* ── Demo bar ──────────────────────────────────────────────────────────── */
.demoBar { display: grid; gap: 10px; padding: 18px 16px 28px; border-top: 1px solid var(--mk-line, #11110f24); }
@container (min-width: 900px) { .demoBar { padding-inline: 40px; } }
.demoControls { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 22px; margin: 0; padding: 10px 14px 12px; border: 1px dashed var(--mk-ink-muted, #5c5a52); border-radius: 10px; }
.demoControls legend { padding: 0 6px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; }
.demoControls legend span { color: var(--mk-ink-muted, #5c5a52); }
.demoCheck { display: inline-flex; align-items: center; gap: 8px; min-height: 32px; font-size: 0.875rem; cursor: pointer; }
.demoCheck input { width: 18px; height: 18px; margin: 0; accent-color: var(--mk-ink, #11110f); }
.fineprint { margin: 0; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }
